	$$$TRACE("In GetUniqueNcidByRep... ") 
	set repNcid = ""
	$$$TRACE("Rep:"_rep_" domain:"_domain_" contextNcid:"_contextNcid) 
	set repNcid = ..GetHddNcidForRepFromHddNcidCache(rep,domain,contextNcid)

    if ( repNcid '= "") {
	    return
    }

    try{
	    $$$TRACE("***********1*********") 
		set servicePort = ##class(HddInterfaceService.InterfaceServicePort).%New()
  	    set servicePort.Location = ..Location	 
    if ('..MultiHddContextsLookup){	  
	    Set repNcid = servicePort.getUniqueNcidByRep(rep, domain, contextNcid, ..dbEnv, 0) 	    
    }else{
	    Set repNcid = servicePort.getNcidsByRep(rep, domain, contextNcid, ..dbEnv, 0)	    
	    if ((repNcid'="")&&$ISOBJECT(repNcid)){
		    set repNcid=repNcid.GetAt(1)
	    }
