    }
 	if ( repNcid '= ""){	 	
		$$$TRACE("getUniqueNcidByRep " _ repNcid) 	
		Do ..InsertValuesToHddNcidCache(repNcid, domain, contextNcid, rep)
		Quit
	} 
	 $$$TRACE("In GetUniqueNcidByRep...repNcid.. "_repNcid)
  }CATCH exceptionvar{	  
	  	throw exceptionvar
   }

