	 //Get current time
 SET todayInt=$PIECE($HOROLOG,",",1)
 SET nowInt=$PIECE($HOROLOG,",",2)
 $$$TRACE( "Now: (" _ todayInt _ ", " _ nowInt _")")


 if ($DATA(^NextRef) = 0)
 {
	 $$$TRACE(  "Set global: ^NextRef")
	 set ^NextRef(1)= todayInt _ "," _ (nowInt - 50)
 }

 // Get Next refresh time
 SET nextdateref=$PIECE($GET(^NextRef(1)),",",1)
 SET nexttimeref=$PIECE($GET(^NextRef(1)),",",2)

 $$$TRACE(  "NEXT REFRESH: (" _ nextdateref _ ", " _ nexttimeref _")")


 if ((todayInt < nextdateref) || ((todayInt = nextdateref) && (nowInt < nexttimeref)) )
 {
	 $$$TRACE( "REFRESH Due on: " _ $ZDATETIME(^NextRef(1)) _ " = " _(nextdateref - todayInt) _ " : " _ (nexttimeref - nowInt))
 }
 else
 {
	 $$$TRACE(  "REFRESH NOW "  _ (nextdateref - todayInt) _ " : " _ (nexttimeref - nowInt))
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.InterfaceHddRepCache)
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.InterfaceHddNcidCache)
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddBillingTypeCache)	 
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddUniqueRepByRepCache)	 
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddHelp1RelationshipCache)	
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddImageExamDescriptionCache)	
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddUniqueChildCache)	
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddIsMemberCache)	
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddIsRodsApptCache)	
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddGetComputritionCache)
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.InterfaceHddMultiNcidsCache)
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddUniqueParentCache)
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddUniqueChildRepByParentRepCache)

	  // Get refresh date and time
	  set hddUpdateDay = ..HddUpdateDay ; Sunday: 0, Monday: 1, Saturday: 6
	  if ( (hddUpdateDay < 0) || (hddUpdateDay > 7))
	  {
		  $$$LOGERROR("HddUpdateDay not set, value should be between 0 and 7")
		  return
	  }

      // Calculate next refresh date...
	  set dayOfWeek = $ZDATE($HOROLOG,10)
	  set daysLeft = $SELECT( (dayOfWeek > hddUpdateDay) : (7 - dayOfWeek + hddUpdateDay),(dayOfWeek = hddUpdateDay) : 7, 1 : (hddUpdateDay - dayOfWeek) )
	  set refdatezh = todayInt + daysLeft

	  // Next refresh time
      SET hddUpdateTime= ..HddUpdateTime  ; format: "hh:mm" (24-hour clock).
      if ( ($MATCH(hddUpdateTime, "\d\d:\d\d") = 1) || ($MATCH(hddUpdateTime, "\d:\d\d") = 1) )
 	  {

 	  	set hddUpdateTimezh = $ZTIMEH(hddUpdateTime,2)
 	  	if (hddUpdateTimezh <= 0)
 	  	{
	 	  	$$$LOGERROR("HddUpdateTime not set")
	 		  return
 	  	}
 	  }
 	  else
 	  {
 	  	$$$LOGERROR("HddUpdateTime not set correctly: HH:MM")
	 	  return
 	  }

      set ^NextRef(1)= refdatezh _ "," _ hddUpdateTimezh
      $$$TRACE(  "NEXT REFRESH: " _ $ZDATETIME(^NextRef(1)))
 }
